import { LitElement, html, unsafeCSS } from "lit";
import { property, state } from "lit/decorators.js";
import { ifDefined } from "lit/directives/if-defined.js";
import {
  NysFormControlElement,
  dispatchNysEvent,
  dispatchNysFocusBlur,
} from "@nysds/internals";
// These internal elements are rendered inside this component's shadow DOM, so
// they must be registered whenever nys-checkboxgroup is used. Importing them
// here (intentional side effect) guarantees the visible label and error message —
// which the accessible name/error association depends on — always render.
import "@nysds/nys-label";
import "@nysds/nys-errormessage";
// @ts-ignore: SCSS module imported via bundler as inline
import styles from "./nys-checkbox.scss?inline";
import type { NysCheckbox } from "./nys-checkbox";

/** Detail payload for the `nys-change` event fired by `nys-checkboxgroup`. */
export interface NysCheckboxgroupChangeDetail {
  id: string;
  name: string;
  value: string[];
}

/** The `nys-change` event fired by `nys-checkboxgroup`. */
export type NysCheckboxgroupChangeEvent =
  CustomEvent<NysCheckboxgroupChangeDetail>;

/**
 * A container for grouping multiple `nys-checkbox` components as a single form control.
 * Handles validation, required constraints, and submits comma-separated values.
 *
 * Use to allow users to select multiple options from a list. Apply `tile` and `size` to the group
 * and all children inherit these styles automatically.
 *
 * @summary Container for grouping checkboxes as a single form control.
 * @element nys-checkboxgroup
 * @formControl value nys-change
 *
 * @slot - Default slot for `nys-checkbox` elements.
 * @slot description - Custom HTML description content.
 *
 * @fires {NysCheckboxgroupChangeEvent} nys-change - Fired when any child checkbox changes. Detail: `{id, name, value}` where `value` is the checked values as a string array. Bubbles and composed. The child's own `nys-change` keeps bubbling alongside it.
 * @fires {Event} nys-focus - Fired when focus enters the group from outside. Bubbles and composed.
 * @fires {Event} nys-blur - Fired when focus leaves the group. Bubbles and composed.
 *
 * @example Basic
 * ```html
 * <nys-checkboxgroup label="Select landmarks" required>
 *   <nys-checkbox name="landmarks" value="adirondacks" label="Adirondacks"></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="niagara" label="Niagara Falls"></nys-checkbox>
 * </nys-checkboxgroup>
 * ```
 *
 * @example Tile
 * ```html
 * <nys-checkboxgroup label="Select landmarks" tile>
 *   <nys-checkbox name="landmarks" value="adirondacks" label="Adirondacks"></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="niagara" label="Niagara Falls"></nys-checkbox>
 * </nys-checkboxgroup>
 * ```
 *
 * @example Required
 * ```html
 * <nys-checkboxgroup label="Select landmarks" required>
 *   <nys-checkbox name="landmarks" value="adirondacks" label="Adirondacks"></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="niagara" label="Niagara Falls"></nys-checkbox>
 * </nys-checkboxgroup>
 * ```
 *
 * @example Optional
 * ```html
 * <nys-checkboxgroup label="Select landmarks" optional>
 *   <nys-checkbox name="landmarks" value="adirondacks" label="Adirondacks"></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="niagara" label="Niagara Falls"></nys-checkbox>
 * </nys-checkboxgroup>
 * ```
 *
 * @example Disabled
 * ```html
 * <nys-checkboxgroup label="Select landmarks">
 *   <nys-checkbox name="landmarks" value="adirondacks" label="Adirondacks" disabled></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="niagara" label="Niagara Falls" disabled></nys-checkbox>
 * </nys-checkboxgroup>
 * ```
 *
 * @example Size Small
 * ```html
 * <nys-checkboxgroup label="Select landmarks" size="sm">
 *   <nys-checkbox name="landmarks" value="adirondacks" label="Adirondacks"></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="niagara" label="Niagara Falls"></nys-checkbox>
 * </nys-checkboxgroup>
 * ```
 *
 * @example Other Option
 * ```html
 * <nys-checkboxgroup label="Select landmarks">
 *   <nys-checkbox name="landmarks" value="adirondacks" label="Adirondacks"></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="niagara" label="Niagara Falls"></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="" label="Other" other></nys-checkbox>
 * </nys-checkboxgroup>
 * ```
 *
 * @example Error Message
 * ```html
 * <nys-checkboxgroup label="Select landmarks" showError errorMessage="Please select at least one landmark">
 *   <nys-checkbox name="landmarks" value="adirondacks" label="Adirondacks"></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="niagara" label="Niagara Falls"></nys-checkbox>
 * </nys-checkboxgroup>
 * ```
 *
 * @example Description
 * ```html
 * <nys-checkboxgroup label="Select landmarks" description="Choose wisely, you can only pick one.">
 *   <nys-checkbox name="landmarks" value="adirondacks" label="Adirondacks"></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="niagara" label="Niagara Falls"></nys-checkbox>
 * </nys-checkboxgroup>
 * ```
 *
 * @example Description Slot
 * ```html
 * <nys-checkboxgroup label="Select landmarks">
 *   <div slot="description">Your <strong>ABSOLUTE</strong> favorite one.</div>
 *   <nys-checkbox name="landmarks" value="adirondacks" label="Adirondacks"></nys-checkbox>
 *   <nys-checkbox name="landmarks" value="niagara" label="Niagara Falls"></nys-checkbox>
 * </nys-checkboxgroup>
 * ```
 */

export class NysCheckboxgroup extends NysFormControlElement {
  static styles = unsafeCSS(styles);
  static shadowRootOptions = {
    ...LitElement.shadowRootOptions,
    delegatesFocus: true,
  };

  /** Unique identifier. Auto-generated if not provided. */
  @property({ type: String, reflect: true }) id = "";

  /** Name for form submission. Set on group, not individual checkboxes. */
  @property({ type: String, reflect: true }) name = "";

  /** Requires at least one checkbox to be checked. */
  @property({ type: Boolean, reflect: true }) required = false;

  /** Shows "Optional" flag. */
  @property({ type: Boolean, reflect: true }) optional = false;

  /** Shows error message when true. */
  @property({ type: Boolean, reflect: true }) showError = false;

  /** Error message text. Shown only when `showError` is true. */
  @property({ type: String }) errorMessage = "";

  /** Visible label text for the group. */
  @property({ type: String }) label = "";

  /** Helper text below label. Use slot for custom HTML. */
  @property({ type: String }) description = "";

  /** Renders all checkboxes as tiles with larger clickable area. */
  @property({ type: Boolean, reflect: true }) tile = false;

  /** Tooltip text shown on hover/focus of info icon. */
  @property({ type: String }) tooltip = "";

  /** Form `id` to associate with. Applied to all children. */
  @property({ type: String, reflect: true }) form: string | null = null;

  /**
   * Checkbox size for all children: `sm` (24px) or `md` (32px, default).
   * @default "md"
   */
  @property({ type: String, reflect: true }) size: "sm" | "md" = "md";

  private _value: string[] = [];

  // Guards the value accessor: true while the group syncs `value` from its
  // children, so the setter doesn't push the same state back down.
  private _syncingValueFromChildren = false;

  /**
   * Values of the checked child checkboxes, in DOM order. Setting it
   * programmatically checks the matching children and updates the form value
   * without firing `nys-change`.
   */
  @property({ attribute: false })
  get value(): string[] {
    return this._value;
  }

  set value(next: string[]) {
    const old = this._value;
    this._value = Array.isArray(next) ? [...next] : [];
    if (!this._syncingValueFromChildren) {
      this._applyValueToChildren();
    }
    this.requestUpdate("value", old);
  }

  @state() private _slottedDescriptionText = "";
  @state() private _hasOtherError = false;
  @state() private _otherErrorCheckbox: NysCheckbox | null = null;

  // Not reactive: only read by event handlers, never by render.
  private _hasSharedNames = false;

  /**
   * Lifecycle methods
   * --------------------------------------------------------------------------
   * Form association, ElementInternals, and id generation are provided by
   * NysFormControlElement (@nysds/internals).
   */

  connectedCallback() {
    // super.connectedCallback() (NysFormControlElement) assigns an id when one
    // is not provided and reflects default semantics.
    super.connectedCallback();
    this.addEventListener("nys-change", this._handleCheckboxChange);
    this.addEventListener("nys-other-input", this._handleOtherInput);
    this.addEventListener("invalid", this._handleInvalid);
    this.addEventListener("nys-error", this._handleChildError);
    this.addEventListener("nys-error-clear", this._handleChildErrorClear);
    this.addEventListener("focusin", this._handleFocusIn);
    this.addEventListener("focusout", this._handleFocusOut);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this.removeEventListener("nys-change", this._handleCheckboxChange);
    this.removeEventListener("nys-other-input", this._handleOtherInput);
    this.removeEventListener("invalid", this._handleInvalid);
    this.removeEventListener("nys-error", this._handleChildError);
    this.removeEventListener("nys-error-clear", this._handleChildErrorClear);
    this.removeEventListener("focusin", this._handleFocusIn);
    this.removeEventListener("focusout", this._handleFocusOut);
  }

  firstUpdated() {
    // This ensures our checkboxes sets the value only once for formData (not within the individual checkboxes)
    this._setGroupExist();
    this._updateCheckboxSize();
    this._updateCheckboxTile();
    this._updateCheckboxShowError();
    // `_getSlotDescriptionForAria` runs off the description slot's `slotchange`
    // instead: setting state here would land after the update completed and
    // force a second render (see lit.dev/msg/change-in-update).
  }

  updated(changedProperties: Map<string | symbol, unknown>) {
    if (changedProperties.has("required")) {
      if (this.required) {
        this._setupCheckboxRequired();
      }
    }
    if (changedProperties.has("size")) {
      this._updateCheckboxSize();
    }
    if (changedProperties.has("tile")) {
      this._updateCheckboxTile();
    }
    if (changedProperties.has("showError")) {
      this._updateCheckboxShowError();
    }
    if (changedProperties.has("form")) {
      this._updateCheckboxForm();
    }
  }

  /**
   * Functions
   * --------------------------------------------------------------------------
   */

  private _hasAtLeastOneChecked() {
    return Array.from(this.querySelectorAll("nys-checkbox")).some(
      (checkbox: any) => checkbox.checked,
    );
  }

  private _setGroupExist() {
    const checkboxes = Array.from(
      this.querySelectorAll("nys-checkbox"),
    ) as NysCheckbox[];

    this._hasSharedNames = this._checkSharedNames(checkboxes);

    checkboxes.forEach((checkbox: any) => {
      checkbox.groupExist = this._hasSharedNames;
    });
  }

  // Initial update on checkbox required attribute
  private async _setupCheckboxRequired() {
    const firstCheckbox = this.querySelector("nys-checkbox");

    const firstCheckboxInput = firstCheckbox
      ? await (firstCheckbox as any).getInputElement()
      : null;

    this.internalValidationMessage = "This field is required";
    this.setValidityFromState(
      { valueMissing: true },
      this.resolvedErrorMessage(),
      firstCheckboxInput ? firstCheckboxInput : this,
    );
  }

  // Updates the required attribute of each checkbox in the group
  private async _manageRequire() {
    if (!this.required) {
      this.clearValidity();
      this.internalValidationMessage = "";
      this.showError = false;
      return;
    }

    const checkboxes = Array.from(
      this.querySelectorAll("nys-checkbox"),
    ) as any[];

    // Loop through each child checkbox to see if one is checked.
    const atLeastOneChecked = this._hasAtLeastOneChecked();

    const firstCheckboxInput = checkboxes
      ? await checkboxes[0].getInputElement().catch(() => null)
      : null;

    // Always clear validation first to prevent message lingering
    this.clearValidity();
    this.internalValidationMessage = "";
    this.showError = false;

    if (!atLeastOneChecked) {
      // Only set valueMissing if there's no active "other" error
      // If there IS an "other" error, keep that as the primary error
      if (!this._hasOtherError) {
        this.internalValidationMessage =
          "You must make a selection to proceed.";
        this.setValidityFromState(
          { valueMissing: true },
          this.resolvedErrorMessage(),
          firstCheckboxInput ?? this,
        );
        this.showError = true;
      } else {
        // Re-set the other error since we just cleared everything
        this._setCustomOtherError();
        this.showError = true;
      }
    } else {
      // At least one checkbox is checked
      // If there's an "other" error, reset it since we cleared everything above
      if (this._hasOtherError && this._otherErrorCheckbox) {
        this._setCustomOtherError();
        this.showError = true;
      }
    }
  }

  private _setCustomOtherError() {
    const textInput =
      this._otherErrorCheckbox?.shadowRoot?.querySelector("nys-textinput");
    const targetElement = textInput || this._otherErrorCheckbox;
    this.internalValidationMessage = "Please complete this field.";
    this.setValidityFromState(
      { customError: true },
      this.resolvedErrorMessage(),
      targetElement as HTMLElement,
    );
  }

  // Updates the size of each checkbox in the group
  private _updateCheckboxSize() {
    const checkboxes = this.querySelectorAll("nys-checkbox");
    checkboxes.forEach((checkbox) => {
      checkbox.setAttribute("size", this.size);
    });
  }

  private _updateCheckboxTile() {
    const checkboxes = this.querySelectorAll("nys-checkbox");
    checkboxes.forEach((checkbox) => {
      if (this.tile) {
        checkbox.toggleAttribute("tile", true);
      } else {
        checkbox.removeAttribute("tile");
      }
    });
  }

  private _updateCheckboxShowError() {
    const checkboxes = this.querySelectorAll("nys-checkbox");
    checkboxes.forEach((checkbox) => {
      if (this.showError) {
        checkbox.setAttribute("showError", "");
      } else {
        checkbox.removeAttribute("showError");
      }
    });
  }

  private _updateCheckboxForm() {
    const checkboxes = this.querySelectorAll("nys-checkbox");
    checkboxes.forEach((checkbox) => {
      if (this.showError) {
        if (this.form !== null) {
          checkbox.setAttribute("form", this.form);
        } else {
          checkbox.removeAttribute("form");
        }
      } else {
        checkbox.removeAttribute("form");
      }
    });
  }

  // Get the slotted text contents so native VO can attempt to announce it within the legend in the fieldset
  private _getSlotDescriptionForAria() {
    const slot = this.shadowRoot?.querySelector(
      'slot[name="description"]',
    ) as HTMLSlotElement;
    const nodes = slot?.assignedNodes({ flatten: true }) || [];

    this._slottedDescriptionText = nodes
      .map((node) => node.textContent?.trim())
      .filter(Boolean)
      .join(", ");
  }

  // This callback is automatically called when the parent form is reset.
  public formResetCallback() {
    // Reset all child checkboxes
    const checkboxes = this.querySelectorAll("nys-checkbox");
    checkboxes.forEach((checkbox: any) => {
      checkbox.formResetCallback();
    });

    this.setFormValue("");
    this._setValueFromChildren([]);

    // Reset validation UI. Clears only the component-owned validation text; a
    // consumer-supplied errorMessage is never overwritten.
    this.showError = false;
    this.internalValidationMessage = "";
    this.clearValidity();

    // Re-render UI
    this.requestUpdate();
  }

  private async _handleInvalid(event: Event) {
    event.preventDefault();

    // Priority 1: Focus "other" text input when customError is set
    if (this.internals?.validity.customError) {
      const checkboxes = Array.from(
        this.querySelectorAll("nys-checkbox"),
      ) as NysCheckbox[];

      const otherCheckbox = checkboxes.find(
        (checkbox) => checkbox.other && checkbox.checked,
      );

      if (otherCheckbox) {
        const textInput =
          otherCheckbox.shadowRoot?.querySelector("nys-textinput");

        if (textInput) {
          await (textInput as any).updateComplete;
          (textInput as HTMLElement).focus();
          return;
        }
      }
    }

    // Priority 2: Handle valueMissing (required validation)
    this.showError = true;
    await this._manageRequire(); // Refresh validation message

    // Fallback behavior
    const firstCheckbox = this.querySelector("nys-checkbox");
    const firstCheckboxInput = firstCheckbox
      ? await (firstCheckbox as any).getInputElement()
      : null;

    if (firstCheckboxInput) {
      // Focus only if this is the first invalid element (top-down approach)
      const form = this.internals?.form;
      if (form) {
        const elements = Array.from(form.elements) as Array<
          HTMLElement & { checkValidity?: () => boolean }
        >;
        // Find the first element in the form that is invalid
        const firstInvalidElement = elements.find((element) => {
          // If element is <nys-checkboxgroup>, we see if anyone checkboxes within the group is checked to fulfill required constraint
          if (element.tagName.toLowerCase() === "nys-checkboxgroup") {
            const allCheckboxes = Array.from(
              this.querySelectorAll("nys-checkbox"),
            ) as any[];
            const hasCheckedCheckbox = allCheckboxes.filter(
              (checkbox) => checkbox.checked,
            );
            // Required constraint not met, continue logic to have this component be focused
            if (hasCheckedCheckbox.length === 0) {
              return element;
            }
          } else {
            return (
              typeof element.checkValidity === "function" &&
              !element.checkValidity()
            );
          }
        });

        if (firstInvalidElement === this) {
          firstCheckboxInput.focus();
        }
      } else {
        // If not part of a form, simply focus.
        firstCheckboxInput.focus();
      }
    }
  }

  /**
   * Event Handlers
   * --------------------------------------------------------------------------
   */

  // Similar to how native forms handle multiple same-name fields, we group the selected values into a list for FormData.
  private _handleCheckboxChange(event: Event) {
    // The group dispatches its own nys-change from this handler; ignore that
    // echo so it isn't handled as another child change.
    if (event.target === this) return;

    const checkboxes = Array.from(
      this.querySelectorAll("nys-checkbox"),
    ) as NysCheckbox[];

    // Filter to only the checked ones and extract their values.
    const selectedValues = checkboxes
      .filter((checkbox) => checkbox.checked)
      .map((checkbox) => checkbox.value);

    if (this._hasSharedNames) {
      const customEvent = event as CustomEvent;
      const { name } = customEvent.detail;

      this.name = name;
      this.setFormValue(selectedValues.join(", "));
    }
    this._setValueFromChildren(selectedValues);

    // Check "other" inputs first (they take priority)
    this._checkOtherInputs(checkboxes);

    // Only run required validation if no "other" error is active
    if (!this._hasOtherError) {
      this._manageRequire();
    }

    dispatchNysEvent<NysCheckboxgroupChangeDetail>(this, "nys-change", {
      id: this.id,
      name: this.name,
      value: [...selectedValues],
    });
  }

  private async _handleChildError(event: Event) {
    event.stopPropagation();

    const { sourceCheckbox } = (event as CustomEvent).detail;
    if (!sourceCheckbox) return;

    // Track which checkbox has the error
    this._hasOtherError = true;
    this._otherErrorCheckbox = sourceCheckbox;
    this.showError = true;

    this._setCustomOtherError();
  }

  private _handleChildErrorClear(event: Event) {
    const customEvent = event as CustomEvent;
    const sourceCheckbox = customEvent.detail?.sourceCheckbox;

    if (
      this._otherErrorCheckbox &&
      sourceCheckbox !== this._otherErrorCheckbox
    ) {
      return;
    }

    // Clear the old validation state first so to prevent the old customError message from persisting
    this._hasOtherError = false;
    this._otherErrorCheckbox = null;
    this.clearValidity();
    this.internalValidationMessage = "";
    this.showError = false;

    // Then check if we need to set a new required error
    if (this.required && !this._hasAtLeastOneChecked()) {
      this._manageRequire();
    }
  }

  private _handleOtherInput() {
    const checkboxes = Array.from(
      this.querySelectorAll("nys-checkbox"),
    ) as NysCheckbox[];
    const selectedValues = checkboxes
      .filter((checkbox: any) => checkbox.checked)
      .map((checkbox: any) => checkbox.value);
    this._setValueFromChildren(selectedValues);
    this.setFormValue(selectedValues.join(", "));
  }

  /**
   * Group-level focus: fired only when focus enters from outside the group,
   * so moving between child checkboxes stays silent.
   */
  private _handleFocusIn = (event: FocusEvent) => {
    const related = event.relatedTarget as Node | null;
    if (!related || !this.contains(related)) {
      dispatchNysFocusBlur(this, "focus");
    }
  };

  /** Group-level blur: fired only when focus leaves the group entirely. */
  private _handleFocusOut = (event: FocusEvent) => {
    const related = event.relatedTarget as Node | null;
    if (!related || !this.contains(related)) {
      dispatchNysFocusBlur(this, "blur");
    }
  };

  /**
   * Set `value` from the children's checked state without pushing the same
   * state back down (and without firing `nys-change`).
   */
  private _setValueFromChildren(values: string[]) {
    this._syncingValueFromChildren = true;
    this.value = values;
    this._syncingValueFromChildren = false;
  }

  /**
   * Apply a programmatically set `value` to the child checkboxes and the form
   * value. Setting `checked` on a child never fires its `nys-change` (only
   * user interaction does), so no change events echo back.
   */
  private _applyValueToChildren() {
    const checkboxes = Array.from(
      this.querySelectorAll("nys-checkbox"),
    ) as NysCheckbox[];
    if (checkboxes.length === 0) return;

    checkboxes.forEach((checkbox) => {
      checkbox.checked = this._value.includes(checkbox.value);
    });

    if (this._hasSharedNames) {
      this.setFormValue(this._value.join(", "));
    }
  }

  /**
   * Derive `value` from the checked children. Runs off the default slot's
   * `slotchange`, so it covers first render and dynamically added checkboxes
   * without scheduling a second update cycle.
   */
  private _handleDefaultSlotChange() {
    const checkboxes = Array.from(
      this.querySelectorAll("nys-checkbox"),
    ) as NysCheckbox[];
    this._setValueFromChildren(
      checkboxes
        .filter((checkbox) => checkbox.checked)
        .map((checkbox) => checkbox.value),
    );
  }

  private async _checkOtherInputs(checkboxes: NysCheckbox[]) {
    for (const checkbox of checkboxes) {
      if (checkbox.checked && checkbox.other) {
        const value = checkbox.value.trim();

        const hasUserInteracted = (checkbox as any)._hasUserInteracted;

        if (!hasUserInteracted) {
          // User hasn't interacted yet, skip validation
          continue;
        }

        if (!value || value === "") {
          this._hasOtherError = true;
          this._otherErrorCheckbox = checkbox;
          this._setCustomOtherError();
          this.showError = true;
          return;
        }
      }
    }

    // If we reached here, no other invalid "other" was found.
    // Clear any previous "other" error
    if (this._hasOtherError) {
      this._hasOtherError = false;
      this._otherErrorCheckbox = null;

      // Re-check required constraint
      if (this.required) {
        this._manageRequire();
      } else {
        this.clearValidity();
        this.internalValidationMessage = "";
        this.showError = false;
      }
    }
  }

  /** Drupal-like naming support **/

  private _checkSharedNames(checkboxes: NysCheckbox[]): boolean {
    if (checkboxes.length === 0) return false;
    const firstName = checkboxes[0].name;
    return checkboxes.every((checkbox) => checkbox.name === firstName);
  }

  render() {
    return html`
      <fieldset
        aria-labelledby=${ifDefined(
          this.label ? this.id + "--label" : undefined,
        )}
        aria-label=${ifDefined(
          !this.label
            ? `${this._slottedDescriptionText || this.description || ""}`.trim() ||
                undefined
            : undefined,
        )}
        class="nys-checkboxgroup"
        role="radiogroup"
      >
        <nys-label
          id="${this.id}--label"
          label=${this.label}
          description=${this.description}
          flag=${this.required ? "required" : this.optional ? "optional" : ""}
          tooltip=${this.tooltip}
        >
          <slot
            name="description"
            slot="description"
            @slotchange=${this._getSlotDescriptionForAria}
            >${this.description}</slot
          >
        </nys-label>
        <div class="nys-checkboxgroup__content">
          <slot @slotchange=${this._handleDefaultSlotChange}></slot>
        </div>
        <nys-errormessage
          id=${this.id + "--error"}
          ?showError=${this.showError}
          errorMessage=${this.resolvedErrorMessage()}
          .showDivider=${!this.tile}
        ></nys-errormessage>
      </fieldset>
    `;
  }
}

if (!customElements.get("nys-checkboxgroup")) {
  customElements.define("nys-checkboxgroup", NysCheckboxgroup);
}
