import { LitElement, html, unsafeCSS } from "lit";
import { property, state, query } from "lit/decorators.js";
import { ifDefined } from "lit/directives/if-defined.js";
import {
  NysFormControlElement,
  dispatchNysEvent,
  dispatchNysFocusBlur,
} from "@nysds/internals";
// These internal elements are rendered inside this component's shadow DOM, so
// they must be registered whenever nys-textinput is used. Importing them here
// (intentional side effect) guarantees the visible label and error message —
// which the accessible name/error association depends on — always render.
// nys-button/nys-icon render the password-visibility toggle and search-clear
// controls.
import "@nysds/nys-label";
import "@nysds/nys-errormessage";
import "@nysds/nys-button";
import "@nysds/nys-icon";
// @ts-ignore: SCSS module imported via bundler as inline
import styles from "./nys-textinput.scss?inline";

/** Detail for the `nys-input` event. */
export interface NysTextinputInputDetail {
  /** The component's `id`. */
  id: string;
  /** The component's `name`. */
  name: string;
  /** The current value. */
  value: string;
}

/** Fired once per user input. */
export type NysTextinputInputEvent = CustomEvent<NysTextinputInputDetail>;

/** Detail for the `nys-change` event. */
export interface NysTextinputChangeDetail {
  /** The component's `id`. */
  id: string;
  /** The component's `name`. */
  name: string;
  /** The committed value. */
  value: string;
}

/** Fired when the value is committed, on blur or Enter. */
export type NysTextinputChangeEvent = CustomEvent<NysTextinputChangeDetail>;

/**
 * A text input for collecting short, single-line data. Supports validation, input masking (tel),
 * password visibility toggle, and live error messaging. Form-associated via ElementInternals.
 *
 * Use for names, emails, passwords, phone numbers. For multi-line input, use `nys-textarea` instead.
 * For predefined options, use `nys-select`, `nys-radiobutton`, or `nys-checkbox`.
 *
 * @summary Text input for short single-line data with validation and masking support.
 * @element nys-textinput
 *
 * @slot description - Custom HTML description content below the label.
 * @slot startButton - Button at input start. Use single `nys-button` only.
 * @slot endButton - Button at input end. Use single `nys-button` only.
 *
 * @formControl value nys-change nys-input
 *
 * @fires {NysTextinputInputEvent} nys-input - Fired once per user input. Detail: `{id, name, value}`.
 * @fires {NysTextinputChangeEvent} nys-change - Fired when the value is committed, on blur or Enter. Detail: `{id, name, value}`.
 * @fires {Event} nys-focus - Fired when the input gains focus.
 * @fires {Event} nys-blur - Fired when the input loses focus. Triggers validation.
 *
 * @usagedos
 * - Use to collect short, single-line, open-ended text input (e.g., names, email addresses, or short descriptions).
 * - Use clear, concise labels that describe the expected input.
 * - Add helper text with the `description` property for context.
 * - Validate input live to catch errors early (e.g., invalid email formats).
 *
 * @usagedonts
 * - Use for long or multi-line responses. Use `<nys-textarea>` instead.
 * - Use when input can be chosen from predefined options. Use `<nys-select>`, `<nys-radiobutton>`, or `<nys-checkbox>` instead.
 * - Overwhelm users with too many fields. Group related inputs.
 * - Use placeholders as labels.
 *
 * @example Basic
 * ```html
 * <nys-textinput label="Full Name"></nys-textinput>
 * ```
 *
 * @example Disabled
 * ```html
 * <nys-textinput label="Email Address" disabled></nys-textinput>
 * ```
 *
 * @example Readonly
 * ```html
 * <nys-textinput label="Email Address" readonly value="You can see me but not edit me"></nys-textinput>
 * ```
 *
 * @example Required
 * ```html
 * <nys-textinput label="Email Address" required></nys-textinput>
 * ```
 *
 * @example Optional
 * ```html
 * <nys-textinput label="Email Address" optional></nys-textinput>
 * ```
 *
 * @example Width Small
 * ```html
 * <nys-textinput label="Zip Code" width="sm"></nys-textinput>
 * ```
 *
 * @example Width Medium
 * ```html
 * <nys-textinput label="City" width="md"></nys-textinput>
 * ```
 *
 * @example Width Large
 * ```html
 * <nys-textinput label="Email Address" width="lg"></nys-textinput>
 * ```
 *
 * @example Description
 * ```html
 * <nys-textinput label="Email Address" description="Only valid ny.gov emails are accepted."></nys-textinput>
 * ```
 *
 * @example Description Slot
 * ```html
 * <nys-textinput label="Email Address">
 *  <div slot="description">Only valid <strong>ny.gov</strong> emails are accepted.</div>
 * </nys-textinput>
 * ```
 *
 * @example Masking
 * ```html
 * <nys-textinput type="tel" label="Phone Number">
 *  <div slot="description">Some types, such as <code>tel</code> have automatic masking available.</div>
 * </nys-textinput>
 * ```
 *
 * @example Password
 * ```html
 * <nys-textinput type="password"></nys-textinput>
 * ```
 *
 * @example Max Min Values
 * ```html
 * <nys-textinput type="number" label="Age" min="18" max="99" width="sm"></nys-textinput>
 * ```
 *
 * @example Suffix Button
 * ```html
 * <nys-textinput id="search-demo" type="search" placeholder="Search">
 *   <nys-button
 *     slot="endButton"
 *     ariaLabel="Search"
 *     prefixIcon="search"
 *     onclick="alert('searching for: ' + document.getElementById('search-demo').value)"
 *   ></nys-button>
 * </nys-textinput>
 * ```
 */

export class NysTextinput extends NysFormControlElement {
  static styles = unsafeCSS(styles);
  static shadowRootOptions = {
    ...LitElement.shadowRootOptions,
    delegatesFocus: true,
  };

  /** Unique identifier. Auto-generated if not provided. */
  @property({ type: String, reflect: true }) id = "";

  /** Name for form submission. */
  @property({ type: String, reflect: true }) name = "";

  /**
   * Input type: `text` (default), `email`, `number`, `password`, `search`, `tel` (auto-masked), `url`.
   * @default "text"
   */
  @property({ type: String, reflect: true }) type:
    | "email"
    | "number"
    | "password"
    | "search"
    | "tel"
    | "text"
    | "url" = "text";

  /** Visible label text. Required for accessibility. */
  @property({ type: String }) label = "";

  /** Helper text below label. Use slot for custom HTML. */
  @property({ type: String }) description = "";

  /** Placeholder text. Don't use as label replacement. */
  @property({ type: String }) placeholder = "";

  /** Current input value. */
  @property({ type: String }) value = "";

  /** Prevents interaction. */
  @property({ type: Boolean, reflect: true }) disabled = false;

  /** Makes input read-only but focusable. */
  @property({ type: Boolean, reflect: true }) readonly = false;

  /** Marks as required. Shows "Required" flag and validates on blur. */
  @property({ type: Boolean, reflect: true }) required = false;

  /** Shows "Optional" flag. Use when most fields are required. */
  @property({ type: Boolean, reflect: true }) optional = false;

  /** Tooltip text shown on hover/focus of info icon. */
  @property({ type: String }) tooltip = "";

  /** Form `id` to associate with when input is outside form element. */
  @property({ type: String, reflect: true }) form: string | null = null;

  /** Regex pattern for validation. Shows error on mismatch. */
  @property({ type: String }) pattern = "";

  /** Maximum character length. */
  @property({ type: Number }) maxlength: number | null = null;

  /** Accessible label. When set, assuming "label" isn't provided for private special cases (i.e., <checkbox other>). */
  @property({ type: String }) ariaLabel = "";

  /**
   * Input width: `sm` (88px), `md` (200px), `lg` (384px), `full` (100%, default).
   * @default "full"
   */
  @property({ type: String, reflect: true }) width:
    | "sm"
    | "md"
    | "lg"
    | "full" = "full";

  /** Step increment for `type="number"`. */
  @property({ type: Number }) step: number | null = null;

  /** Minimum value for `type="number"`. */
  @property({ type: Number }) min: number | null = null;

  /** Maximum value for `type="number"`. */
  @property({ type: Number }) max: number | null = null;

  /** Adjusts colors for dark backgrounds. */
  @property({ type: Boolean, reflect: true }) inverted = false;

  /** Shows error message when true. Set by validation or manually. */
  @property({ type: Boolean, reflect: true }) showError = false;

  /** Error message text. Shown only when `showError` is true. */
  @property({ type: String }) errorMessage = "";

  @query("input") private _inputEl!: HTMLInputElement;

  @state() private showPassword = false;

  private _hasUserInteracted = false; // need this flag for "eager mode"

  private _maskPatterns: Record<string, string> = {
    tel: "(___) ___-____",
  };

  /**
   * Lifecycle methods
   * --------------------------------------------------------------------------
   * Form association, ElementInternals, and id generation are provided by
   * NysFormControlElement (@nysds/internals).
   */
  connectedCallback() {
    // super.connectedCallback() (NysFormControlElement) assigns an id when one
    // is not provided and reflects default semantics.
    super.connectedCallback();
    this.addEventListener("invalid", this._handleInvalid);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this.removeEventListener("invalid", this._handleInvalid);
  }

  async firstUpdated() {
    // This ensures our element always participates in the form
    this._setValue();
  }

  // Ensure the "width" property is valid after updates
  async updated(changedProperties: Map<string | number | symbol, unknown>) {
    if (changedProperties.has("value")) {
      this._setValue();
    }

    if (changedProperties.has("disabled")) {
      this._validateButtonSlot("startButton");
      this._validateButtonSlot("endButton");
    }

    if (changedProperties.has("type")) {
      const mask = this._maskPatterns[this.type];
      const input = this._inputEl;

      if (input) {
        if (mask) {
          // Only apply mask length if user hasn't explicitly set maxlength
          if (this.maxlength === null) {
            input.maxLength = mask.length;
          }
          this._updateOverlay(input.value, mask);
        } else {
          // Only remove if user hasn't explicitly set maxlength
          if (this.maxlength === null) {
            input.removeAttribute("maxLength");
          }
          const overlay = this.shadowRoot?.querySelector(
            ".nys-textinput__mask-overlay",
          );
          if (overlay) overlay.textContent = "";
        }
      }
    }
    if (
      changedProperties.has("readonly") ||
      changedProperties.has("required")
    ) {
      const input = this._inputEl;

      if (input) input.required = this.required && !this.readonly;

      // Re-sync ElementInternals, not just the shadow <input>: `required`
      // can arrive as a late property write (e.g. a framework wrapper
      // setting it post-hydration, after firstUpdated already ran
      // _setValue()/_manageRequire() once against the old value). Without
      // this, ElementInternals keeps reporting valid, the native `invalid`
      // event never fires on submit, and showError never flips even though
      // the field is genuinely required and empty. Harmless to re-run
      // alongside the value-driven call above: _manageRequire() only
      // re-derives state from current `value`/`required`.
      this._manageRequire();
    }
  }

  /**
   * Form Integration
   * --------------------------------------------------------------------------
   */

  private _setValue() {
    this.setFormValue(this.value);
    this._manageRequire(); // Update validation
  }

  private _manageRequire() {
    const input = this._inputEl;

    if (!input) return;

    const message = this.resolvedErrorMessage() || "This field is required";
    const isInvalid =
      this.required && (!this.value || this.value?.trim() === ""); // Check for blank as well

    if (isInvalid) {
      this.setValidityFromState({ valueMissing: true }, message, input);
    } else {
      this.clearValidity();
      this._hasUserInteracted = false; // Reset eager/lazy checking
    }
  }

  private _setValidityMessage(message: string = "") {
    const input = this._inputEl;
    if (!input) return;

    // Always show the visual error if there is a message
    this.showError = !!message;

    // Store validation output separately. A consumer-supplied errorMessage is
    // never overwritten; resolvedErrorMessage() gives it precedence.
    this.internalValidationMessage = message;

    if (message) {
      this.setValidityFromState(
        { customError: true },
        this.resolvedErrorMessage(),
        input,
      );
    } else {
      this.clearValidity();
    }
  }

  private _validate() {
    const input = this._inputEl;
    if (!input) return;

    // Get the native validation state
    const validity = input.validity;
    let message = "";

    // Check each possible validation error
    if (validity.valueMissing) {
      message = "This field is required";
    } else if (validity.typeMismatch) {
      message = "Invalid format for this type";
    } else if (validity.patternMismatch) {
      message = "Invalid format";
    } else if (validity.tooShort) {
      message = `Value is too short. Minimum length is ${input.minLength}`;
    } else if (validity.tooLong) {
      message = `Value is too long. Maximum length is ${input.maxLength}`;
    } else if (validity.rangeUnderflow) {
      message = `Value must be at least ${input.min}`;
    } else if (validity.rangeOverflow) {
      message = `Value must be at most ${input.max}`;
    } else if (validity.stepMismatch) {
      message = "Invalid step value";
    } else {
      message = input.validationMessage;
    }

    this._setValidityMessage(message);
  }

  // This callback is automatically called when the parent form is reset.
  public formResetCallback() {
    this.value = "";

    const input = this._inputEl;
    if (input) {
      input.value = "";
    }

    this.setFormValue("");

    // Reset validation UI. Clears only the component's own validation text; a
    // consumer-supplied errorMessage is never overwritten.
    this.showError = false;
    this.internalValidationMessage = "";
    this.clearValidity();

    this.showPassword = false;

    // Reset mask overlay if applicable
    const mask = this._maskPatterns[this.type];
    if (mask) {
      this._updateOverlay("", mask);
    }

    // Re-render UI
    this.requestUpdate();
  }

  /**
   * Functions
   * --------------------------------------------------------------------------
   */

  // This helper function is called to perform the element's native validation.
  checkValidity(): boolean {
    const input = this._inputEl;
    return input ? input.checkValidity() : true;
  }

  private _handleInvalid(event: Event) {
    event.preventDefault();
    this._hasUserInteracted = true; // Start aggressive mode due to form submission
    this._validate();

    const input = this._inputEl;
    if (input) {
      // Focus only if this is the first invalid element (top-down approach)
      const form = this.internals?.form;
      if (form) {
        const elements = Array.from(form.elements) as Array<
          HTMLElement & { checkValidity?: () => boolean }
        >;
        // Find the first element in the form that is invalid
        const firstInvalidElement = elements.find(
          (element) =>
            typeof element.checkValidity === "function" &&
            !element.checkValidity(),
        );
        if (firstInvalidElement === this) {
          input.focus();
        }
      } else {
        // If not part of a form, simply focus.
        input.focus();
      }
    }
  }

  private _togglePasswordVisibility() {
    this.showPassword = !this.showPassword;
  }

  private _clearSearch() {
    this.value = "";

    const input = this._inputEl;
    if (input) {
      input.value = "";
      input.focus();
    }

    this.setFormValue("");

    if (this._hasUserInteracted) {
      this._validate();
    }

    this._emitInput();
  }

  private _updateOverlay(value: string, mask: string) {
    const overlay = this.shadowRoot?.querySelector(
      ".nys-textinput__mask-overlay",
    ) as HTMLElement;
    if (!overlay) return;

    const filled = value;
    const remaining = mask.slice(filled.length);
    overlay.textContent = filled + remaining;
  }

  private _applyMask(value: string, mask: string): string {
    const digits = value.replace(/\D/g, "");
    let result = "";

    // Special handling for tel to avoid trailing dash
    if (this.type === "tel") {
      if (digits.length > 0) {
        result = "(" + digits.substring(0, 3);
      }
      if (digits.length >= 4) {
        result += ") " + digits.substring(3, 6);
      }
      // Add dash if there are more than 6 digits
      if (digits.length > 6) {
        result += "-" + digits.substring(6, 10);
      }
      return result;
    }

    // Default generic masking logic
    let digitIndex = 0;
    for (let i = 0; i < mask.length; i++) {
      if (mask[i] === "_" || mask[i].match(/[d9]/i)) {
        if (digitIndex < digits.length) {
          result += digits[digitIndex++];
        } else {
          break;
        }
      } else {
        result += mask[i]; // keep formatting symbols
      }
    }

    return result;
  }

  /**
   * Event Handlers
   * --------------------------------------------------------------------------
   */

  // Handle input event to check pattern validity
  private _handleInput(event: Event) {
    const input = event.target as HTMLInputElement;
    let newValue = input.value;

    const mask = this._maskPatterns[this.type];
    if (mask) {
      newValue = this._applyMask(newValue, mask);
      input.value = newValue; // ensure input reflects masked value
      this._updateOverlay(newValue, mask);
    }

    this.value = newValue;
    this.setFormValue(this.value);

    // Field is invalid after unfocused, validate aggressively on each input (e.g. Eager mode: a combination of aggressive and lazy.)
    if (this._hasUserInteracted) {
      this._validate();
    }

    this._emitInput();
  }

  // Single dispatch site for nys-input, so it fires exactly once per input.
  private _emitInput() {
    dispatchNysEvent<NysTextinputInputDetail>(this, "nys-input", {
      id: this.id,
      name: this.name,
      value: this.value,
    });
  }

  // Handle native change: the value is committed, on blur or Enter.
  private _handleChange() {
    dispatchNysEvent<NysTextinputChangeDetail>(this, "nys-change", {
      id: this.id,
      name: this.name,
      value: this.value,
    });
  }

  // Handle focus event
  private _handleFocus() {
    dispatchNysFocusBlur(this, "focus");
  }

  // Handle blur event
  private _handleBlur() {
    if (!this._hasUserInteracted) {
      this._hasUserInteracted = true; // At initial unfocus: if input is invalid, start aggressive mode
    }
    this._validate();

    dispatchNysFocusBlur(this, "blur");
  }

  private _validateButtonSlot(slotName: string) {
    const slot = this.shadowRoot?.querySelector(
      'slot[name="' + slotName + '"]',
    ) as HTMLSlotElement;
    const container = this.shadowRoot?.querySelector(
      ".nys-textinput__buttoncontainer",
    );

    if (!slot || !container) return;

    const assignedElements = slot.assignedElements();

    let foundValidButton = false;

    assignedElements.forEach((node) => {
      const isNysButton =
        node instanceof HTMLElement &&
        node.tagName.toLowerCase() === "nys-button";

      if (isNysButton && !foundValidButton) {
        // First valid nys-button found
        foundValidButton = true;
        node.setAttribute("size", "sm");
        node.setAttribute("variant", "primary");
        //set button to be disabled if the input is disabled
        if (this.disabled) {
          node.setAttribute("disabled", "true");
        } else {
          node.removeAttribute("disabled");
        }
      } else {
        console.warn(
          "The '" +
            slotName +
            "' slot only accepts a single <nys-button> element. Removing invalid or extra node:",
          node,
        );
        node.remove();
      }
    });

    if (slotName === "startButton") {
      container.classList.toggle("has-start-button", foundValidButton);
    } else if (slotName === "endButton") {
      container.classList.toggle("has-end-button", foundValidButton);
    }
  }

  render() {
    return html`
      <div class="nys-textinput">
        <nys-label
          id="${this.id}--label"
          label=${this.label}
          description=${this.description}
          flag=${this.required && !this.readonly
            ? "required"
            : this.optional
              ? "optional"
              : ""}
          tooltip=${this.tooltip}
          ?inverted=${this.inverted}
        >
          <slot name="description" slot="description">${this.description}</slot>
        </nys-label>
        <div class="nys-textinput__buttoncontainer">
          <slot
            name="startButton"
            @slotchange=${() => this._validateButtonSlot("startButton")}
          ></slot>
          <div class="nys-textinput__container">
            <span class="nys-textinput__mask-overlay"></span>
            <input
              class="nys-textinput__input"
              type=${this.type === "password"
                ? this.showPassword
                  ? "text"
                  : "password"
                : this.type}
              name=${this.name}
              id=${this.id + "--native"}
              ?disabled=${this.disabled}
              ?required=${this.required && !this.readonly}
              ?readonly=${this.readonly}
              aria-labelledby=${ifDefined(
                this.label ? this.id + "--label" : undefined,
              )}
              aria-label=${ifDefined(
                !this.label && this.ariaLabel ? this.ariaLabel : undefined,
              )}
              aria-required=${this.required}
              aria-disabled="${this.disabled}"
              aria-invalid=${this.showError ? "true" : "false"}
              aria-errormessage=${this.id + "--error"}
              aria-describedby=${ifDefined(
                this.showError ? this.id + "--error" : undefined,
              )}
              .value=${this.value}
              placeholder=${ifDefined(
                this.placeholder ? this.placeholder : undefined,
              )}
              pattern=${ifDefined(this.pattern ? this.pattern : undefined)}
              min=${ifDefined(this.min !== null ? this.min : undefined)}
              maxlength=${ifDefined(
                this.maxlength !== null ? this.maxlength : undefined,
              )}
              step=${ifDefined(this.step !== null ? this.step : undefined)}
              max=${ifDefined(this.max !== null ? this.max : undefined)}
              form=${ifDefined(this.form || undefined)}
              @input=${this._handleInput}
              @change=${this._handleChange}
              @focus="${this._handleFocus}"
              @blur="${this._handleBlur}"
            />
            ${this.type === "password"
              ? html` <nys-button
                  class="inline-icon"
                  id="password-toggle"
                  ariaLabel="password toggle"
                  variant="ghost"
                  circle
                  size="sm"
                  @nys-click=${() =>
                    !this.disabled && this._togglePasswordVisibility()}
                >
                  <nys-icon
                    slot="circle-icon"
                    size="2xl"
                    name=${this.showPassword ? "visibility_off" : "visibility"}
                  ></nys-icon>
                </nys-button>`
              : ""}
            ${this.type === "search" &&
            this.value &&
            !this.disabled &&
            !this.readonly
              ? html` <nys-button
                  class="inline-icon"
                  id="search-clear"
                  ariaLabel="clear search"
                  variant="ghost"
                  circle
                  size="sm"
                  @nys-click=${() => this._clearSearch()}
                >
                  <nys-icon
                    slot="circle-icon"
                    size="2xl"
                    name="close"
                  ></nys-icon>
                </nys-button>`
              : ""}
          </div>
          <slot
            name="endButton"
            @slotchange=${() => this._validateButtonSlot("endButton")}
          ></slot>
        </div>
        <nys-errormessage
          id=${this.id + "--error"}
          ?showError=${this.showError}
          errorMessage=${this.resolvedErrorMessage()}
        ></nys-errormessage>
      </div>
    `;
  }
}

if (!customElements.get("nys-textinput")) {
  customElements.define("nys-textinput", NysTextinput);
}
